          <tr>
            <th>✅ Gut geeignet für …</th>
            <th>❌ Weniger geeignet für …</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>Familien mit Kindern (jedes Alters)</td>
            <td>Wenig aktive Menschen / Couch-Potatoes</td>
          </tr>
          <tr>
