            <td>Menschen mit Putzfimmel (Haare!)</td>
          </tr>
          <tr>
            <td>Hundeanfänger mit Zeit und Motivation</td>
            <td>Beruflich Vielreisende (ohne Hundebetreuung)</td>
          </tr>
          <tr>
            <td>Wanderer, Jogger, Wassersportler</td>
            <td>Allergiker (starkes Haaren)</td>
          </tr>
          <tr>
            <td>Menschen mit Haus und / oder Garten</td>
            <td>Menschen mit geringem Zeitbudget</td>
          </tr>
          <tr>
            <td>Hundesport-Interessierte</td>
            <td>Senioren mit eingeschränkter Mobilität</td>
          </tr>
        </tbody>
