  padding:.35rem .5rem;
  border-radius:8px;
  color:var(--text);
  font-size:.82rem;
  font-weight:500;
  transition:all .15s;
  text-decoration:none;
  line-height:1.3;
}
.mega-col a:hover{
  background:var(--primary-light);
  color:var(--primary-dark);
  text-decoration:none;
}
.mega-col a .badge{
  font-size:.6rem;
  background:var(--primary);
  color:#fff;
  padding:.1rem .4rem;
  border-radius:20px;
  font-weight:700;
  margin-left:auto;
  animation:pulse-badge 2s infinite;
}
@keyframes pulse-badge{
  0%,100%{opacity:1}
  50%{opacity:.6}
}
.mega-col a .desc{
  font-size:.68rem;
