"""Batch-update all article HTML files to use the mega menu header.
Handles both multiline and minified CSS/HTML variants."""
import os, glob, re

ARTIKEL_DIR = "C:/HermesPortable/home/scripts/blog-automation/haustier-zentrum/artikel"

# ─── CSS replacements ───

# Old multiline header CSS (with newlines)
OLD_CSS_MULTI = """.site-header{
  background:var(--bg);
  border-bottom:2px solid var(--primary);
  padding:0 1rem;
  position:sticky;
  top:0;
  z-index:100;
}
.nav-wrap{
  max-width:1100px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  height:64px;
}
.logo{
  font-size:1.4rem;
  font-weight:800;
  color:var(--primary);
  letter-spacing:-.5px;
}
.logo:hover{text-decoration:none}
.nav-links{display:flex;gap:1.5rem;list-style:none}
.nav-links a{
  color:var(--text);
  font-weight:500;
  font-size:.95rem;
  padding:.3rem 0;
  border-bottom:2px solid transparent;
  transition:.2s;
}
.nav-links a:hover,.nav-links a.active{
  color:var(--primary);
  border-bottom-color:var(--primary);
  text-decoration:none;
}
.nav-toggle{display:none;background:none;border:none;font-size:1.6rem;cursor:pointer;color:var(--text);padding:.25rem;}
main{flex:1;max-width:1100px;margin:0 auto;padding:2rem 1rem;width:100%}"""

# Old minified header CSS (single line)
OLD_CSS_MIN = ".site-header{background:var(--bg);border-bottom:2px solid var(--primary);padding:0 1rem;position:sticky;top:0;z-index:100}.nav-wrap{max-width:1100px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;height:64px}.logo{font-size:1.4rem;font-weight:800;color:var(--primary);letter-spacing:-.5px}.logo:hover{text-decoration:none}.nav-links{display:flex;gap:1.5rem;list-style:none}.nav-links a{color:var(--text);font-weight:500;font-size:.95rem;padding:.3rem 0;border-bottom:2px solid transparent;transition:.2s}.nav-links a:hover,.nav-links a.active{color:var(--primary);border-bottom-color:var(--primary);text-decoration:none}.nav-toggle{display:none;background:none;border:none;font-size:1.6rem;cursor:pointer;color:var(--text);padding:.25rem}main{flex:1;max-width:1100px;margin:0 auto;padding:2rem 1rem;width:100%}"

NEW_CSS_HEADER = """.site-header{
  background:rgba(255,255,255,.92);
  backdrop-filter:blur(16px) saturate(1.2);
  border-bottom:3px solid var(--primary);
  padding:0 1rem;
  position:sticky;
  top:0;
  z-index:1000;
}
.nav-wrap{
  max-width:1200px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  height:72px;
}
.logo{
  font-size:1.4rem;
  font-weight:900;
  letter-spacing:-1px;
  background:linear-gradient(135deg,var(--primary-dark),var(--primary));
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
  flex-shrink:0;
}
.logo span{font-weight:400;color:var(--text-muted);-webkit-text-fill-color:var(--text-muted);}
.logo:hover{text-decoration:none}
.main-nav{display:flex;align-items:center}
.nav-links{display:flex;gap:0;list-style:none;align-items:center;margin:0;padding:0}
.nav-links > li{position:relative}
.nav-links > li > a{
  color:var(--text);
  font-weight:600;
  font-size:.85rem;
  padding:.4rem 1rem;
  border-radius:50px;
  transition:.2s;
  letter-spacing:.2px;
  display:flex;
  align-items:center;
  gap:.3rem;
  white-space:nowrap;
}
.nav-links > li > a .arrow{
  font-size:.6rem;
  transition:transform .25s;
  display:inline-block;
}
.nav-links > li:hover > a .arrow{
  transform:rotate(180deg);
}
.nav-links > li > a:hover,
.nav-links > li > a.active{
  color:#fff;
  background:var(--primary);
  text-decoration:none;
}
.nav-links > li.simple-link > a{
  color:var(--text-muted);
  font-weight:500;
  font-size:.8rem;
}
.nav-links > li.simple-link > a:hover{
  color:#fff;
}
.mega-panel{
  position:absolute;
  top:100%;
  left:50%;
  transform:translateX(-50%) translateY(12px);
  background:#fff;
  border-radius:16px;
  box-shadow:0 20px 60px rgba(0,0,0,.15), 0 4px 20px rgba(0,0,0,.06);
  min-width:680px;
  max-width:900px;
  padding:0;
  opacity:0;
  visibility:hidden;
  transition:all .25s cubic-bezier(.16,1,.3,1);
  border:1px solid var(--border-light);
  overflow:hidden;
  pointer-events:none;
}
.nav-links > li:hover .mega-panel{
  opacity:1;
  visibility:visible;
  transform:translateX(-50%) translateY(8px);
  pointer-events:auto;
}
.mega-grid{
  display:grid;
  gap:0;
  padding:1.5rem;
}
.mega-grid.cols-2{grid-template-columns:1fr 1fr}
.mega-grid.cols-3{grid-template-columns:1fr 1fr 1fr}
.mega-grid.cols-4{grid-template-columns:1fr 1fr 1fr 1fr}
.mega-col{
  padding:0 .8rem;
  border-right:1px solid var(--border-light);
}
.mega-col:last-child{border-right:none}
.mega-col h4{
  font-size:.7rem;
  text-transform:uppercase;
  letter-spacing:1px;
  color:var(--primary);
  font-weight:700;
  margin:0 0 .6rem 0;
  padding-bottom:.4rem;
  border-bottom:2px solid var(--primary-light);
}
.mega-col a{
  display:flex;
