for fname in files_to_fix:
    fpath = base + fname
    with open(fpath, 'r', encoding='utf-8') as f:
        content = f.read()

    orig = content
    changes = []

    # CSS
    if OLD_CSS_V3 in content:
        content = content.replace(OLD_CSS_V3, NEW_CSS)
        changes.append("CSS v3")

    # Mobile CSS
    if OLD_MOBILE_V3 in content:
        content = content.replace(OLD_MOBILE_V3, NEW_MOBILE_CSS)
        changes.append("mobile")

    # Fix any duplicate --border-light
    # Count occurrences
    bl_count = content.count('--border-light')
    if bl_count > 1:
        # Remove the duplicate
        lines = content.split('\n')
        seen = False
        new_lines = []
        for line in lines:
            if '--border-light' in line:
                if seen:
                    continue
                seen = True
            new_lines.append(line)
        content = '\n'.join(new_lines)
        changes.append("dedup border-light")

    # Remove duplicate --primary-light if exists before it's defined
    # Actually let me just check if border-light is there already

    if '--border-light' not in content:
        # Need to add it
        old = "  --border: #e0e0e0;\n  --card-shadow: 0 2px 12px rgba(0,0,0,.08);"
        new = "  --border: #e0e0e0;\n  --border-light: #f0ece1;\n  --card-shadow: 0 2px 12px rgba(0,0,0,.08);"
        if old in content:
            content = content.replace(old, new)
            changes.append("border-light")

    if content != orig:
        with open(fpath, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f"✅ {fname}: {', '.join(changes)}")
    else:
        print(f"⏭️ {fname}: no changes needed")

print("Done with remaining files!")
